/* Lede look "skeuo" (Skeuomorphic): the rules no token reaches. Its token values are in ./skeuo.tokens.css, which the token build
   writes from `looks` in tokens/tokens.json. Turn it on with <ThemeProvider look="skeuo">, or data-look="skeuo" on a theme root.

   The rules sit in an @scope that stops at a theme root with another look or none, so they reach only what the look's own
   provider holds, as its tokens do. `:scope` stands for the look's root. Each rule is a candidate for the next token. */
@import "./skeuo.tokens.css";

/* ═════════════════════════════ SKEUOMORPHIC ("Workshop") ═════════════════════════════
   Light from above: gradients, bevels, wells, embossed type and linen behind it all. */
@scope ([data-look="skeuo"]) to ([data-theme]:not([data-look="skeuo"])) {
  /* Beyond tokens: embossed type. A text-shadow token would carry it. */
  :scope .ld-btn:is(.ld-btn-filled, .ld-btn-critical.ld-btn-filled) { text-shadow: 0 -1px 0 rgba(0, 0, 0, 0.25); }
  :scope :is(.ld-page-title, .ld-list-title, .ld-shell-brand) { text-shadow: 0 1px 0 rgba(255, 255, 255, 0.75); }
  @container style(--ld-scheme: dark) {
    :scope :is(.ld-page-title, .ld-list-title, .ld-shell-brand) { text-shadow: 0 -1px 0 rgba(0, 0, 0, 0.8); }
  }
  /* Depth that high contrast trades for its own edges, so these stay out of -hc. */
  @container style(--ld-contrast: standard) {
    /* The open row sits pressed into the list, as a well, not only tinted. */
    :scope .ld-row:has(.ld-row-target[aria-current="page"]) { box-shadow: var(--depth-well); }
    /* The sidebar is a panel of its own, lit from above and bevelled where it meets the page. */
    :scope .ld-shell-sidebar { background-image: linear-gradient(to bottom, rgba(255, 255, 255, 0.22), rgba(255, 255, 255, 0) 40%); box-shadow: inset -1px 0 0 rgba(255, 255, 255, 0.35); }
    /* Unread marks and avatars are glossy beads: a highlight up top, a shade below. */
    :scope :is(.ld-unread-dot, .ld-avatar) { background-image: radial-gradient(circle at 35% 25%, rgba(255, 255, 255, 0.55), rgba(255, 255, 255, 0) 60%); box-shadow: inset 0 -1px 2px rgba(0, 0, 0, 0.3), 0 1px 0 rgba(255, 255, 255, 0.6); }
  }
  @container style(--ld-contrast: standard) and style(--ld-scheme: dark) {
    :scope .ld-shell-sidebar { background-image: linear-gradient(to bottom, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0) 40%); box-shadow: inset -1px 0 0 rgba(255, 255, 255, 0.05); }
    :scope :is(.ld-unread-dot, .ld-avatar) { box-shadow: inset 0 -1px 2px rgba(0, 0, 0, 0.45), 0 1px 0 rgba(255, 255, 255, 0.08); }
  }
}

/* Lede look "skeuo" (Skeuomorphic) — GENERATED from tokens/tokens.json by scripts/build-tokens.mjs. Do not edit. */

@scope ([data-look="skeuo"]) to ([data-look]:not([data-look="skeuo"]) [data-theme]) {
  :where([data-theme][data-look]:not([data-look="skeuo"])) {
    --radius: 22px;
    --radius-capsule: 999px;
    --radius-step: 8px;
    --font-sans: -apple-system, BlinkMacSystemFont, system-ui, "Segoe UI", "Helvetica Neue", Arial, sans-serif;
    --blur-regular: 24px;
    --press-transform: initial;
    --depth-pressed: inset 0 0 transparent;
    --edge-surface: 0 0 transparent;
    --depth-control: 0 0 transparent;
    --sheen-control: none;
    --depth-well: 0 0 transparent;
    --texture-ground: none;
  }
}

[data-theme][data-look="skeuo"] {
  --radius: 10px;
  --radius-capsule: 10px;
  --radius-step: 3px;
  --font-sans: "Lucida Grande", "Helvetica Neue", "DejaVu Sans", Helvetica, Arial, sans-serif;
  --blur-regular: 6px;
  --press-transform: none;
  --depth-pressed: inset 0 2px 4px rgba(0, 0, 0, 0.35);
}

[data-theme^="light"][data-look="skeuo"] {
  --edge-surface: 0 0 0 1px var(--border), 0 1px 0 rgba(255, 255, 255, 0.9) inset, 0 1px 2px rgba(40, 30, 10, 0.3), 0 2px 6px rgba(40, 30, 10, 0.12);
  --depth-control: inset 0 0 0 1px rgba(0, 0, 0, 0.25), 0 1px 0 rgba(255, 255, 255, 0.9) inset, 0 1px 2px rgba(40, 30, 10, 0.35);
  --sheen-control: linear-gradient(to bottom, rgba(255, 255, 255, 0.4), rgba(255, 255, 255, 0) 50%, rgba(0, 0, 0, 0.08));
  --depth-well: inset 0 2px 3px rgba(0, 0, 0, 0.18), 0 1px 0 rgba(255, 255, 255, 0.6);
}

[data-theme="light"][data-look="skeuo"] {
  --primary: #1d55ad;
  --primary-foreground: #ffffff;
  --background: #f4f1ea;
  --background-grouped: #dcd7cc;
  --card: #fbf9f4;
  --muted: #ebe6db;
  --foreground: #2a2620;
  --muted-foreground: #595246;
  --fill-control: rgba(90, 75, 50, 0.12);
  --fill-control-strong: rgba(90, 75, 50, 0.28);
  --fill-selected: #fffdf8;
  --fill-knob: #fdfcf9;
  --border: rgba(60, 45, 20, 0.22);
  --input: #736a5f;
  --glass-tint: rgba(236, 232, 223, 0.94);
  --glass-stroke: rgba(40, 30, 10, 0.35);
  --glass-highlight: #ffffff;
  --shadow-raised: 0 1px 0 rgba(255, 255, 255, 0.9) inset, 0 1px 2px rgba(40, 30, 10, 0.35), 0 2px 6px rgba(40, 30, 10, 0.15);
  --shadow-float: 0 1px 0 rgba(255, 255, 255, 0.8) inset, 0 12px 28px rgba(40, 30, 10, 0.32), 0 2px 4px rgba(40, 30, 10, 0.3);
  --shadow-knob: 0 0 0 1px #5f574b, 0 2px 4px rgba(40, 30, 10, 0.4), inset 0 1px 0 #ffffff;
  --texture-ground: repeating-linear-gradient(45deg, rgba(0, 0, 0, 0.025) 0 2px, transparent 2px 4px), repeating-linear-gradient(-45deg, rgba(255, 255, 255, 0.05) 0 2px, transparent 2px 4px);
  --destructive: #a11f26;
  --success: #175a2b;
  --warning: #6f4600;
  --preset-blue: #0857b8;
  --preset-indigo: #464ac9;
  --preset-teal: #00676c;
  --preset-green: #1a6631;
  --preset-orange: #9a4200;
  --preset-pink: #b61756;
}

[data-theme^="dark"][data-look="skeuo"] {
  --edge-surface: 0 0 0 1px rgba(0, 0, 0, 0.6), 0 1px 0 rgba(255, 255, 255, 0.1) inset, 0 2px 6px rgba(0, 0, 0, 0.5);
  --depth-control: inset 0 0 0 1px rgba(0, 0, 0, 0.5), 0 1px 0 rgba(255, 255, 255, 0.12) inset, 0 1px 3px rgba(0, 0, 0, 0.6);
  --sheen-control: linear-gradient(to bottom, rgba(255, 255, 255, 0.16), rgba(255, 255, 255, 0) 50%, rgba(0, 0, 0, 0.12));
  --depth-well: inset 0 2px 3px rgba(0, 0, 0, 0.5), 0 1px 0 rgba(255, 255, 255, 0.06);
}

[data-theme="dark"][data-look="skeuo"] {
  --shadow-knob: 0 0 0 1px #000000, 0 2px 4px rgba(40, 30, 10, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.45);
  --primary: #6ea7ff;
  --primary-foreground: #06111f;
  --background: #2b2722;
  --background-grouped: #1d1a17;
  --card: #34302a;
  --muted: #3d3832;
  --foreground: #f1ebe0;
  --muted-foreground: #c4bbad;
  --fill-control: rgba(255, 240, 210, 0.08);
  --fill-control-strong: rgba(255, 240, 210, 0.18);
  --fill-selected: #4a443c;
  --fill-knob: #e8e2d6;
  --border: rgba(0, 0, 0, 0.55);
  --input: #9f978a;
  --glass-tint: rgba(48, 44, 38, 0.95);
  --glass-stroke: rgba(0, 0, 0, 0.7);
  --glass-highlight: rgba(255, 255, 255, 0.12);
  --shadow-raised: 0 1px 0 rgba(255, 255, 255, 0.08) inset, 0 1px 3px rgba(0, 0, 0, 0.7);
  --shadow-float: 0 1px 0 rgba(255, 255, 255, 0.08) inset, 0 14px 30px rgba(0, 0, 0, 0.6);
  --texture-ground: repeating-linear-gradient(45deg, rgba(255, 255, 255, 0.015) 0 2px, transparent 2px 4px);
  --destructive: #ffaeae;
  --success: #5ad27a;
  --preset-blue: #61a6ff;
  --preset-indigo: #9597ff;
  --preset-pink: #ff78a9;
}

[data-theme="light-hc"][data-look="skeuo"] {
  --texture-ground: none;
}

[data-theme="dark-hc"][data-look="skeuo"] {
  --texture-ground: none;
}
